import { Avatar } from "@atlas/ui-web/primitives/Avatar/Avatar"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@atlas/ui-web/primitives/Select/Select"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { Table, TableBody, TableCaption, TableCell, TableHead, TableHeader, TableRow } from "@atlas/ui-web/primitives/Table/Table"

type Role = "Owner" | "Admin" | "Member"
type Member = { id: string; name: string; email: string; initials: string; role: Role; pending?: boolean; you?: boolean }

const ROLES: Role[] = ["Owner", "Admin", "Member"]

const title = { fontSize: "var(--atlas-text-h1)" }
const muted = { fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }

export function MembersPage({ members, loading, onInvite, onChangeRole, onRemove }: {
  members: Member[]
  loading?: boolean
  /** Rejects with a readable reason on failure. */
  onInvite: (email: string, role: Role) => Promise<void>
  /** Rejects when the role could not be saved; the Select then reverts. */
  onChangeRole: (id: string, role: Role) => Promise<void>
  onRemove: (id: string) => void
}) {
  const [inviteOpen, setInviteOpen] = React.useState(false)
  const [email, setEmail] = React.useState("")
  const [inviteRole, setInviteRole] = React.useState<Role>("Member")
  const [sending, setSending] = React.useState(false)
  const [failure, setFailure] = React.useState<string | null>(null)
  const [removing, setRemoving] = React.useState<Member | null>(null)
  const [pendingRole, setPendingRole] = React.useState<Record<string, Role>>({})

  const owners = members.filter((m) => m.role === "Owner" && !m.pending)
  const lastOwner = owners.length === 1 ? owners[0] : null
  const roleOf = (m: Member) => pendingRole[m.id] ?? m.role

  const send = async () => {
    setSending(true)
    setFailure(null)
    try {
      await onInvite(email, inviteRole)
      setInviteOpen(false)
      setEmail("")
    } catch (e) {
      // Keep the Dialog open and the typed email so the user can retry.
      setFailure(e instanceof Error ? e.message : "The invite could not be sent.")
    } finally {
      setSending(false)
    }
  }

  const changeRole = async (m: Member, role: Role) => {
    setPendingRole((s) => ({ ...s, [m.id]: role }))
    try {
      await onChangeRole(m.id, role)
      toast({ variant: "success", title: `${m.name} is now ${role === "Admin" ? "an" : "a"} ${role}` })
    } catch {
      toast({ variant: "danger", title: "Role not changed", description: `${m.name} is still ${m.role}. Try again.` })
    } finally {
      // Saved: the members prop carries the new role. Failed: the Select reverts to the old one.
      setPendingRole((s) => Object.fromEntries(Object.entries(s).filter(([id]) => id !== m.id)))
    }
  }

  return (
    <div style={{ display: "grid", gap: "var(--atlas-spacing-4)", maxInlineSize: "48rem" }}>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-4)" }}>
        <h1 style={title}>Members</h1>
        <Button variant="primary" onClick={() => setInviteOpen(true)}>Invite member</Button>
      </div>

      {lastOwner && (
        <Alert
          variant="info"
          title={`${lastOwner.name} is the only Owner`}
          description={`Make another member an Owner before changing this role or removing ${lastOwner.name}.`}
        />
      )}

      {loading ? (
        <div role="status" aria-label="Loading members" style={{ display: "grid", gap: "var(--atlas-spacing-4)" }}>
          <Skeleton />
          <Skeleton />
          <Skeleton />
          <Skeleton />
        </div>
      ) : (
        <Card variant="outlined">
          <CardHeader><CardTitle>Members</CardTitle></CardHeader>
          <CardContent>
            <Table>
              <TableCaption>Workspace members</TableCaption>
              <TableHeader>
                <TableRow>
                  <TableHead scope="col">Member</TableHead>
                  <TableHead scope="col">Role</TableHead>
                  <TableHead scope="col">Status</TableHead>
                  <TableHead scope="col"><span style={{ position: "absolute", inlineSize: 1, blockSize: 1, overflow: "hidden", clipPath: "inset(50%)" }}>Actions</span></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {members.map((m) => {
                  const protectedOwner = m.id === lastOwner?.id
                  return (
                    <TableRow key={m.id}>
                      <TableCell>
                        <span style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
                          <Avatar size="sm" initials={m.initials} alt="" />
                          <span style={{ display: "grid" }}>
                            <span>{m.name}{m.you ? " (You)" : ""}</span>
                            <span style={muted}>{m.email}</span>
                          </span>
                        </span>
                      </TableCell>
                      <TableCell>
                        {m.pending ? (
                          <span style={muted}>Invited as {m.role}</span>
                        ) : (
                          <Select value={roleOf(m)} onValueChange={(v) => changeRole(m, v as Role)} disabled={protectedOwner}>
                            <SelectTrigger aria-label={`Role for ${m.name}`}><SelectValue /></SelectTrigger>
                            <SelectContent>
                              {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                            </SelectContent>
                          </Select>
                        )}
                      </TableCell>
                      <TableCell>
                        <Badge variant={m.pending ? "warning" : "success"} size="md">{m.pending ? "Pending" : "Active"}</Badge>
                      </TableCell>
                      <TableCell align="end">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm" aria-label={`Actions for ${m.name}`}>More</Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent>
                            {m.pending ? (
                              <>
                                <DropdownMenuItem>Resend invite</DropdownMenuItem>
                                <DropdownMenuItem destructive>Revoke invite</DropdownMenuItem>
                              </>
                            ) : (
                              <DropdownMenuItem destructive disabled={protectedOwner} onSelect={() => setRemoving(m)}>
                                Remove from workspace
                              </DropdownMenuItem>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}

      <Dialog open={inviteOpen} onOpenChange={setInviteOpen}>
        <DialogContent size="md">
          <DialogHeader><DialogTitle>Invite member</DialogTitle></DialogHeader>
          <DialogBody>
            <DialogDescription>
              They will get an email with a link to join. Owners can manage billing; Admins can manage members; Members can edit content.
            </DialogDescription>
            {failure && <Alert variant="danger" description={failure} />}
            <Field label="Email address" required>
              {(control) => <Input {...control} type="email" placeholder="name@company.com" value={email} onChange={(e) => setEmail(e.target.value)} />}
            </Field>
            <Field label="Role">
              {(control) => (
                <Select value={inviteRole} onValueChange={(v) => setInviteRole(v as Role)}>
                  <SelectTrigger {...control}><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                  </SelectContent>
                </Select>
              )}
            </Field>
          </DialogBody>
          <DialogFooter>
            <DialogClose><Button variant="ghost">Cancel</Button></DialogClose>
            <Button variant="primary" loading={sending} disabled={!email.trim()} onClick={send}>Send invite</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={removing !== null} onOpenChange={(o) => { if (!o) setRemoving(null) }}>
        <AlertDialogContent variant="destructive">
          <AlertDialogTitle>Remove {removing?.name}?</AlertDialogTitle>
          <AlertDialogDescription>
            {removing?.name.split(" ")[0]} loses access to this workspace and its projects immediately. Their work stays. You can invite them again later.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={() => { if (removing) onRemove(removing.id) }}>Remove {removing?.name.split(" ")[0]}</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

